/*
 Noは他との兼ね合いで、作成開始時ではなく、保存時に入れることにする。
 //h4_StartRevisionの処理を流用
*/

Innovator inn = this.getInnovator();

const string h4_DATMaster = "h4_DATMaster";
const string DATMasterRel = "h4_DATMaster RevisionHistory";
const string h4_DATFormat = "h4_DATFormat";
const string DATFormatRel = "h4_DATFormat RevisionHistory";
const string NumberIni = "NOTE_";
const string RevisionNumSetProperty = "h4_revision_number";//h4_revision_number


//何かあって値が入力済みなら飛ばす
if(this.getProperty(RevisionNumSetProperty,"") != "")
{
    return this;
}


var parentItemType = h4_DATMaster;
var parentID = this.getProperty("h4_rel_dat_master","");
var targetPropName = "h4_rel_dat_master";
if(parentID == "")
{
    parentItemType = h4_DATFormat;
    parentID = this.getProperty("h4_rel_dat_format","");
    targetPropName = "h4_rel_dat_format";
}

//どこから実行したか確認する。実行した箇所によって、処理を変更する
var relItemNames = "";  
// 対象：XXをセット＋後続処理のためのリレーション名指定
if(parentItemType == h4_DATMaster)
{
    //帳票マスタから作成時
    relItemNames = DATMasterRel;
}
else if(parentItemType == h4_DATFormat)
{   //開達書式から作成時
    relItemNames = DATFormatRel;
}


// MEMO: 親を保存せずに2つ以上作成した場合、リレーションがまだできていないので番号が被る

// // リレーションシップより指摘No.の最大値を取得
