//         int tmpInt = int.Parse(tmpsplit[1]);
        
//         if (tmpInt > maxPointNumber) {
//             maxPointNumber = tmpInt;
//         }
//     }
// }

// maxPointNumber++;
// string tmpRevisionNum = NumberIni + maxPointNumber.ToString("D3");//3桁0埋め

// MEMO: onAfterAddのthisはaddの結果なのでactionがない上に、プロパティが全部入っているのでそのまま使わない方がよい

// var item = this;
// item.setProperty(RevisionNumSetProperty,tmpRevisionNum);



Item maxNumItems = inn.newItem("h4_RevisionHistory", "get");
maxNumItems.setAttribute("select", RevisionNumSetProperty);
maxNumItems.setAttribute("orderBy", RevisionNumSetProperty+" desc"); // TODO: No.が999を超えた場合ソートが正しく動かない
maxNumItems.setProperty(targetPropName, parentID);
maxNumItems = maxNumItems.apply();

// 検索結果の先頭アイテムからNo.生成
string tmpRevisionNum;
if(maxNumItems.getItemCount()>0){
    Item maxNumItem = maxNumItems.getItemByIndex(0);
    var revisionNum = maxNumItem.getProperty(RevisionNumSetProperty,"");
    var tmpsplit = revisionNum.Split("_"); // "Note"
    
    //return inn.newError("katotest h4_SetNos 取得できた|"+targetPropName+"|"+parentID);
    if(tmpsplit.Length == 1) 
    {
        //分割不能＝値が入ってないリレーションのみ取得されたということ
        tmpRevisionNum = NumberIni + "001";
    }
    else
    {
        // 分割可能＝値の入ったものが取れた
        int maxPointNumber = int.Parse(tmpsplit[1]);
        maxPointNumber++;
        tmpRevisionNum = NumberIni + maxPointNumber.ToString("D3");
    }
    

}else{
    //return inn.newError("katotest h4_SetNos 取得できなかった");
    tmpRevisionNum = NumberIni + "001";
}

var item = inn.newItem(this.getType(), "edit");
item.setID(this.getID());
item.setAttribute("version", "0");
item.setAttribute("doGetItem", "0");
item.setProperty(RevisionNumSetProperty,tmpRevisionNum);

Item retItem = null;

using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{ 
    retItem = item.apply();
    if(retItem.isError())
    {
        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
    }
}

return retItem;
